"""Second generator: small domains, dense truth, designed to yield eligible clauses."""
import json, random, sys

NUM = ("TIME", "SIZE", "COUNT")


def gen(rng):
    K = rng.choice([1, 1, 1, 2, 2, 3])
    nfields = rng.randint(1, 4)
    fields = []
    names = rng.sample(["a", "b", "c", "d", "e", "f"], nfields)
    for nm in names:
        t = rng.choice(["FLAG", "FLAG", "SIZE", "COUNT", "TIME", "ID"])
        if t == "FLAG":
            fields.append({"name": nm, "type": "FLAG"})
        elif t == "ID":
            vals = rng.sample(["x", "y", "z", "p.q"], rng.randint(2, 3))
            fields.append({"name": nm, "type": "ID", "values": vals})
        else:
            lo = 0
            hi = rng.randint(0, 3)
            fields.append({"name": nm, "type": t, "min": lo, "max": hi})

    def rand_value(f):
        if f["type"] == "FLAG":
            return rng.choice([True, False])
        if f["type"] == "ID":
            return rng.choice(f["values"])
        return rng.randint(f["min"], f["max"])

    def term(ftype, quant, depth):
        cands = [f for f in fields if f["type"] == ftype]
        r = rng.random()
        if not cands or r < 0.45:
            if ftype == "FLAG":
                return {"const": rng.choice([True, False]), "type": "FLAG"}
            if ftype == "ID":
                allv = set()
                for f in fields:
                    if f["type"] == "ID":
                        allv.update(f["values"])
                return {"const": rng.choice(sorted(allv) or ["q"]), "type": "ID"}
            return {"const": rng.randint(-1, 4), "type": ftype}
        if quant and rng.random() < 0.5:
            return {"field": rng.choice(cands)["name"], "at": "$"}
        if ftype in NUM and depth < 3 and rng.random() < 0.2:
            kind = rng.choice(["scale", "add", "agg"])
            if kind == "scale":
                return {"scale": rng.randint(-2, 4), "term": term(ftype, quant, depth + 1)}
            if kind == "add":
                return {"add": [term(ftype, quant, depth + 1), term(ftype, quant, depth + 1)]}
            f = rng.choice(cands)
            a = rng.randrange(K)
            z = rng.randint(a, K - 1)
            return {"aggregate": rng.choice(["sum", "mean", "min", "max"]),
                    "field": f["name"], "from": a, "to": z}
        return {"field": rng.choice(cands)["name"], "at": rng.randrange(K)}

    def cmp_node(quant):
        ftypes = [f["type"] for f in fields]
        if not ftypes:
            return None
        ftype = rng.choice(ftypes)
        ops = ["eq", "ne", "lt", "le", "gt", "ge"] if ftype in NUM else ["eq", "ne"]
        return {"cmp": rng.choice(ops), "left": term(ftype, quant, 1),
                "right": term(ftype, quant, 1)}

    natoms = rng.randint(1, 6)
    atoms = []
    for _ in range(natoms):
        if rng.random() < 0.3:
            a = rng.randrange(K)
            z = rng.randint(a, K - 1)
            atoms.append({"quantifier": rng.choice(["any", "all"]), "from": a,
                          "to": z, "predicate": cmp_node(True)})
        else:
            atoms.append(cmp_node(False))
    # sometimes duplicate an atom AST under a new index
    if atoms and rng.random() < 0.4 and len(atoms) < 20:
        atoms.append(json.loads(json.dumps(rng.choice(atoms))))
    if atoms and rng.random() < 0.25 and len(atoms) < 20:
        atoms.append(json.loads(json.dumps(rng.choice(atoms))))

    def mk_trace(tid, srcs, nmin, nmax):
        n = rng.randint(nmin, nmax)
        ts = rng.sample(range(0, 500), n)
        rows = [{"t": t, "values": [rand_value(f) for f in fields]} for t in ts]
        return {"id": tid, "source": rng.choice(srcs), "rows": rows}

    nsrc = rng.randint(1, 3)
    srcs = ["s%d" % i for i in range(nsrc)]
    train = [mk_trace("tr%d" % i, srcs, 0, 7) for i in range(rng.randint(1, 4))]
    probes = [mk_trace("pr%d" % i, srcs, 1, 4) for i in range(rng.randint(0, 3))]
    queries = [mk_trace("q%d" % i, srcs, 1, 5) for i in range(rng.randint(0, 3))]
    return {"version": 1, "window": K, "schema": fields, "atoms": atoms,
            "policy": {"max_width": rng.choice([1, 2, 2, 3, 4]),
                       "min_support": rng.choice([1, 1, 1, 2]),
                       "min_witness": rng.choice([1, 1, 1, 2])},
            "train": train, "probes": probes, "queries": queries}


if __name__ == "__main__":
    rng = random.Random(int(sys.argv[1]))
    sys.stdout.write(json.dumps(gen(rng)))
